  static String t(String language, String key) =>
      _values[language]?[key] ?? _values['en']?[key] ?? key;

  static String eligibilityLabel(String language, String status) {
    final key = switch (status) {
      'LIKELY_ELIGIBLE' => 'likely',
      'POTENTIALLY_ELIGIBLE' => 'potential',
      'NOT_ELIGIBLE' => 'notEligible',
      _ => 'insufficient',
    };
    return t(language, key);
  }
